-- Tabla de políticas legales DRALO (generado desde Word en politicas RPD/)
-- Ejecutar en Supabase SQL Editor

CREATE TABLE IF NOT EXISTS public.politicas (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug TEXT NOT NULL UNIQUE,
  titulo TEXT NOT NULL,
  categoria TEXT NOT NULL DEFAULT 'legal',
  orden INT NOT NULL DEFAULT 0,
  actualizado TEXT,
  intro TEXT,
  secciones JSONB NOT NULL DEFAULT '[]'::jsonb,
  publicado BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.politicas ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS politicas_public_read ON public.politicas;
CREATE POLICY politicas_public_read ON public.politicas
  FOR SELECT USING (publicado = true);

DROP POLICY IF EXISTS politicas_service_all ON public.politicas;
CREATE POLICY politicas_service_all ON public.politicas
  FOR ALL TO service_role USING (true) WITH CHECK (true);


INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'politica-privacidad',
  'Política de privacidad',
  'privacidad',
  1,
  '19/05/2026',
  'POLÍTICA DE PRIVACIDADÚltima actualización: 19/05/2026En Dralo respetamos la privacidad de las personas usuarias y nos comprometemos a tratar sus datos personales de forma lícita, leal, transparente y segura.Esta Política de Privacidad explica cómo recogemos, utilizamos y protegemos los datos personales de las personas que acceden o utilizan la web https://www.dralo.es/ y sus servicios asociados, incluyendo la plataforma de aprendizaje de inglés, el registro de usuario, los recursos formativos, el chat o asistente interactivo, los formularios de contacto y, en su caso, futuras funcionalidades de pago.',
  '[{"number":1,"title":"1. Responsable del tratamiento","body":"El responsable del tratamiento de los datos personales es:Titular: Carlos García CanoNIF/CIF: [●]Domicilio: C/ Canillas 57.Nombre comercial: DraloWeb: https://www.dralo.es/Email de contacto en privacidad: draloenglish@gmail.comFormulario de contacto: disponible en la web"},{"number":2,"title":"2. Qué es","body":"DraloDralo es una plataforma online orientada al aprendizaje del inglés y a la preparación de exámenes.La plataforma puede incluir contenidos teóricos, ejercicios, pruebas de nivel, entrenamiento, descarga de recursos, funcionalidades interactivas, corrección automática y asistencia mediante herramientas de inteligencia artificial.Actualmente la plataforma se ofrece de forma gratuita. En el futuro, Dralo podrá incorporar servicios de pago, suscripciones, cursos premium u otras formas de monetización."},{"number":3,"title":"3. Datos personales que tratamos","body":"En función del uso que hagas de la web o plataforma, podremos tratar las siguientes categorías de datos:a) Datos identificativos y de contactoNombre, dirección de correo electrónico y datos incluidos voluntariamente en formularios, mensajes o comunicaciones.b) Datos de registro y cuenta de usuarioDatos necesarios para crear y gestionar una cuenta, como nombre, email, credenciales de acceso, identificador de usuario, fecha de alta, configuración de cuenta y preferencias.c) Datos académicos o de uso de la plataformaInformación relacionada con el uso de Dralo, como ejercicios realizados, respuestas, progreso, nivel estimado, resultados, interacciones con contenidos, historial de actividad, recursos descargados y uso de funcionalidades de aprendizaje.d) Datos enviados a través de formularios, chat o soporteMensajes enviados mediante formularios de contacto, chat, solicitudes de soporte, consultas, incidencias o comunicaciones similares.e) Datos técnicos y de navegaciónDirección IP, identificadores online, tipo de dispositivo, navegador, sistema operativo, registros técnicos, fecha y hora de acceso, páginas visitadas, interacciones con la web y datos derivados del uso de cookies o tecnologías similares.f) Datos para comunicaciones comercialesCorreo electrónico, consentimiento prestado, preferencias de comunicación, historial de envíos y métricas básicas de interacción, como apertura o clics, cuando se utilicen herramientas de email marketing.g) Datos de pago y facturaciónDralo trata datos necesarios para gestionar pagos, facturación, suscripciones, comprobantes, historial de compras, datos fiscales y datos de transacción.En principio, los datos completos de tarjeta u otros medios de pago serán tratados directamente por las pasarelas de pago correspondientes, como PayPal, Redsys u otros proveedores equivalentes, sin que Dralo almacene los datos completos del medio de pago salvo que se indique expresamente lo contrario."},{"number":4,"title":"4. Finalidades y bases jurídicas del tratamiento","body":"Tratamos los datos personales para las siguientes finalidades:FinalidadDatos tratadosBase jurídicaCrear y gestionar cuentas de usuarioNombre, email, credenciales, datos de cuentaEjecución de la relación con el usuario y aceptación de los términos de usoPermitir el uso de la plataforma educativaDatos de cuenta, progreso, ejercicios, respuestas, nivel, actividadEjecución del servicio solicitadoOfrecer ejercicios, correcciones y asistencia interactivaRespuestas, mensajes, interacciones, datos académicosEjecución del servicio y, en su caso, consentimiento cuando se usen funciones opcionalesResponder consultas y solicitudesDatos de contacto y contenido del mensajeConsentimiento del usuario al enviar la consulta y/o interés legítimo en atender la solicitudGestionar descargas de recursosNombre, email, recurso solicitado, registro de descargaConsentimiento o ejecución de la solicitud realizada por el usuarioEnviar comunicaciones comerciales o informativasEmail, consentimiento, preferenciasConsentimiento del usuarioAnalizar el uso de la web y mejorar la plataformaDatos técnicos, navegación, estadísticas, cookiesConsentimiento para cookies analíticas y/o interés legítimo en métricas agregadas no intrusivasGarantizar la seguridad de la webIP, logs, registros técnicos, actividad sospechosaInterés legítimo en proteger la plataforma y prevenir abusosGestionar pagos y facturación, cuando se habilitenDatos de compra, pago, facturación, transacciónEjecución contractual y cumplimiento de obligaciones legalesCumplir obligaciones legalesDatos necesarios según la obligación aplicableCumplimiento de obligaciones legales"},{"number":5,"title":"5. Uso de inteligencia artificial y asistente interactivo","body":"Dralo puede utilizar herramientas de inteligencia artificial para ofrecer funcionalidades como práctica conversacional, corrección automática, generación de ejercicios, explicación de errores o asistencia personalizada en el aprendizaje del inglés.Cuando utilices estas funciones, el contenido que introduzcas en el chat o en los ejercicios podrá ser tratado para generar respuestas, correcciones o recomendaciones formativas.Te recomendamos no introducir información sensible o innecesaria en los chats, ejercicios o campos abiertos, como datos de salud, documentación oficial, contraseñas, datos bancarios, información íntima o datos de terceros.Cuando Dralo utilice proveedores externos de inteligencia artificial, como OpenAI/ChatGPT u otros servicios equivalentes, dichos proveedores podrán tratar los datos necesarios para prestar la funcionalidad contratada, conforme a sus propias condiciones, acuerdos de tratamiento de datos y medidas de seguridad aplicables. Si se usa OpenAI en modalidad API o servicio empresarial, OpenAI indica que puede actuar como encargado del tratamiento respecto de los datos de cliente conforme a su Data Processing Addendum; si se usa ChatGPT como servicio de usuario final, aplican sus políticas generales de privacidad. (OpenAI)"},{"number":6,"title":"6. Comunicaciones comerciales","body":"Si marcas la casilla correspondiente o prestas tu consentimiento por otro medio válido, podremos enviarte comunicaciones comerciales, novedades, recursos, promociones, información sobre cursos, funcionalidades, contenidos educativos o futuras opciones de pago de Dralo.Podrás darte de baja en cualquier momento mediante el enlace incluido en cada comunicación o escribiendo a draloenglish@gmail.comNo enviaremos comunicaciones comerciales electrónicas no solicitadas salvo que exista una base legal que lo permita."},{"number":7,"title":"7. Cookies, analítica y tecnologías similares","body":"Dralo utiliza cookies y tecnologías similares para permitir el funcionamiento de la web, mantener sesiones de usuario, mejorar la experiencia, recordar preferencias y, en su caso, obtener estadísticas de uso.Las cookies técnicas o necesarias pueden instalarse para permitir el funcionamiento básico de la plataforma. Las cookies analíticas, publicitarias o de terceros solo se utilizarán cuando corresponda según la configuración de consentimiento del usuario.Dralo puede utilizar herramientas como Google Analytics para analizar el uso de la web. Google ofrece condiciones de tratamiento de datos para clientes de Analytics afectados por el RGPD y marcos de transferencia internacional como el Data Privacy Framework y/o cláusulas contractuales tipo, según el caso. (Asistencia de Google)Puedes consultar más información en la Política de Cookies de Dralo."},{"number":8,"title":"8. Destinatarios y proveedores con acceso a datos","body":"Para prestar el servicio, Dralo puede contar con proveedores externos que actúan como encargados del tratamiento o prestadores de servicios. Entre ellos pueden encontrarse:Proveedor de hosting y dominio: DonDominio, con infraestructura o prestación de servicios en España. Herramientas de analítica: Google Analytics. Proveedores de inteligencia artificial: OpenAI/ChatGPT u otros equivalentes. Herramientas de desarrollo, repositorios o mantenimiento técnico: Cursor, GitHub u otras herramientas técnicas. Herramientas de organización interna: Notion. Pasarelas de pago: PayPal, Redsys u otras entidades de pago. Proveedores de email, soporte, automatización, seguridad o comunicaciones, si se incorporan en el futuro. Estos proveedores solo accederán a los datos necesarios para prestar sus servicios y deberán ofrecer garantías adecuadas de confidencialidad, seguridad y cumplimiento normativo.También podremos comunicar datos cuando exista obligación legal, requerimiento de autoridad competente, necesidad de defensa jurídica o cumplimiento de obligaciones fiscales, contables o administrativas."},{"number":9,"title":"9. Transferencias internacionales de datos","body":"Algunos proveedores tecnológicos pueden estar ubicados fuera del Espacio Económico Europeo o tratar datos desde países que no ofrecen un nivel de protección equivalente al europeo.Cuando sea necesario realizar transferencias internacionales de datos, Dralo procurará que se realicen con garantías adecuadas, como decisiones de adecuación, cláusulas contractuales tipo aprobadas por la Comisión Europea, acuerdos de tratamiento de datos, medidas técnicas y organizativas complementarias, o cualquier otro mecanismo válido conforme al RGPD.Esto puede resultar especialmente relevante en el uso de proveedores como Google, OpenAI, GitHub, Notion, PayPal u otros servicios tecnológicos internacionales."},{"number":10,"title":"10. Plazos de conservación","body":"Conservaremos los datos personales durante el tiempo necesario para cumplir las finalidades para las que fueron recogidos y, posteriormente, durante los plazos exigidos por la normativa aplicable o mientras puedan derivarse responsabilidades.En particular:Los datos de cuenta se conservarán mientras la cuenta permanezca activa. Los datos de progreso, ejercicios y actividad se conservarán mientras sean necesarios para prestar el servicio educativo. Los datos de consultas y soporte se conservarán durante el tiempo necesario para atender la solicitud y acreditar la gestión realizada. Los datos asociados a comunicaciones comerciales se conservarán hasta que retires tu consentimiento o solicites la baja. Los datos técnicos y logs de seguridad se conservarán durante el tiempo necesario para garantizar la seguridad, prevenir abusos o resolver incidencias. Los datos de facturación y pagos, cuando existan, se conservarán durante los plazos legalmente exigibles por normativa fiscal, contable o mercantil. Cuando solicites la supresión de tus datos, podremos conservarlos bloqueados durante los plazos necesarios para atender posibles responsabilidades legales."},{"number":11,"title":"11. Menores de edad","body":"Dralo está dirigido a personas interesadas en preparar exámenes oficiales de inglés. Aunque el servicio puede resultar útil para estudiantes menores de edad, no está específicamente diseñado para recoger datos de menores de 14 años sin autorización de sus representantes legales.Si eres menor de 14 años, no debes registrarte ni enviar datos personales sin el consentimiento de tu madre, padre, tutor o representante legal.Si Dralo detecta que ha recogido datos de un menor de 14 años sin la autorización correspondiente, adoptará medidas razonables para eliminar dichos datos o solicitar la autorización necesaria.En caso de que seas madre, padre, tutor o representante legal y creas que un menor ha facilitado datos personales en Dralo sin autorización, puedes contactar con nosotros en draloenglish@gmail.com"},{"number":12,"title":"12. Derechos de las personas usuarias","body":"Puedes ejercer los siguientes derechos en materia de protección de datos:Derecho de acceso: saber qué datos tratamos sobre ti. Derecho de rectificación: corregir datos inexactos o incompletos. Derecho de supresión: solicitar la eliminación de tus datos. Derecho de oposición: oponerte a determinados tratamientos. Derecho de limitación: solicitar que limitemos el tratamiento de tus datos. Derecho de portabilidad: recibir tus datos en formato estructurado, cuando proceda. Derecho a retirar el consentimiento en cualquier momento, sin que ello afecte a la licitud del tratamiento realizado previamente. Para ejercer tus derechos, puedes escribir a:Email: draloenglish@gmail.comAsunto recomendado: “Ejercicio de derechos de protección de datos”Podremos solicitar información adicional para verificar tu identidad cuando sea necesario.Si consideras que no hemos tratado tus datos correctamente, también puedes presentar una reclamación ante la Agencia Española de Protección de Datos (AEPD)."},{"number":13,"title":"13. Seguridad de los datos","body":"Dralo aplica medidas técnicas y organizativas razonables para proteger los datos personales frente a pérdida, uso indebido, acceso no autorizado, alteración, divulgación o destrucción.Entre otras medidas, la plataforma puede utilizar cifrado de comunicaciones mediante HTTPS, control de accesos, autenticación de usuarios, limitación de permisos, revisión de incidencias, registros técnicos y medidas de seguridad asociadas al hosting y a los proveedores tecnológicos utilizados.No obstante, ningún sistema conectado a Internet puede garantizar una seguridad absoluta, por lo que el usuario también debe adoptar medidas razonables, como proteger sus credenciales de acceso y no compartir contraseñas."},{"number":14,"title":"14. Exactitud de los datos","body":"El usuario garantiza que los datos personales facilitados son veraces, exactos y actualizados.Si tus datos cambian, deberás comunicárnoslo o actualizarlos desde tu cuenta."},{"number":15,"title":"15. Datos de terceros","body":"No debes facilitar datos personales de otras personas salvo que cuentes con autorización suficiente para hacerlo.En particular, no debes introducir en formularios, ejercicios, chats o mensajes datos personales de terceros, información sensible o contenidos que no sean necesarios para el uso educativo de la plataforma."},{"number":16,"title":"16. Baja de cuenta","body":"Puedes solicitar la eliminación de tu cuenta escribiendo a draloenglish@gmail.com o utilizando las opciones disponibles en la plataforma.La eliminación de la cuenta puede implicar la pérdida de acceso a contenidos, progreso, historial de ejercicios, configuraciones y funcionalidades asociadas.Determinados datos podrán conservarse bloqueados cuando sea necesario para cumplir obligaciones legales, atender responsabilidades o garantizar la seguridad de la plataforma."},{"number":17,"title":"17. Cambios en esta","body":"Política de PrivacidadDralo podrá modificar esta Política de Privacidad para adaptarla a cambios legales, técnicos, organizativos o funcionales.Cuando los cambios sean relevantes, se informará a los usuarios por medios razonables, como aviso en la web, comunicación por email o notificación dentro de la plataforma.La versión vigente será la publicada en cada momento en esta página."}]'::jsonb
)
ON CONFLICT (slug) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  categoria = EXCLUDED.categoria,
  orden = EXCLUDED.orden,
  actualizado = EXCLUDED.actualizado,
  intro = EXCLUDED.intro,
  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'politica-cookies',
  'Política de cookies',
  'privacidad',
  2,
  '19/05/2026',
  'POLÍTICA DE COOKIESÚltima actualización: 19/05/2026En Dralo utilizamos cookies y tecnologías similares para garantizar el funcionamiento de nuestra web y plataforma, recordar determinadas preferencias, mejorar la experiencia de usuario y, cuando el usuario lo autorice, obtener estadísticas de uso mediante herramientas de análisis.Esta Política de Cookies explica qué son las cookies, qué tipos de cookies utilizamos, para qué sirven, quién las gestiona y cómo puedes aceptarlas, rechazarlas, configurarlas o eliminarlas.',
  '[{"number":1,"title":"1. Responsable de la web","body":"El responsable de esta web es:Titular: Carlos García CanoNIF/CIF: [●]Domicilio: C/ Canillas 57.Nombre comercial: DraloEmail de contacto: draloenglish@gmail.com"},{"number":2,"title":"2. Qué son las cookies","body":"Las cookies son pequeños archivos que se descargan en el dispositivo del usuario cuando accede a determinadas páginas web.Sirven para almacenar y recuperar información sobre la navegación, el dispositivo utilizado, la sesión iniciada, las preferencias del usuario o la forma en que interactúa con la web.También pueden utilizarse tecnologías similares, como píxeles, etiquetas, identificadores locales, almacenamiento local del navegador o herramientas equivalentes."},{"number":3,"title":"3. Qué tipos de cookies utiliza","body":"DraloEn Dralo podemos utilizar las siguientes categorías de cookies:a) Cookies técnicas o necesariasSon cookies imprescindibles para que la web y la plataforma funcionen correctamente.Permiten, por ejemplo:Mantener la sesión iniciada. Gestionar el registro y acceso de usuarios. Recordar la configuración básica de privacidad. Proteger la web frente a usos indebidos. Permitir la navegación por las distintas secciones. Gestionar funciones básicas del chat, ejercicios, recursos o formularios. Estas cookies no requieren consentimiento, ya que son necesarias para prestar el servicio solicitado por el usuario.b) Cookies de preferencias o personalizaciónPermiten recordar determinadas opciones elegidas por el usuario, como idioma, configuración visual, preferencias de uso o ajustes de la plataforma.Cuando estas cookies sean elegidas directamente por el usuario y se utilicen solo para recordar sus preferencias, podrán considerarse técnicas. Si se utilizan para otras finalidades, se solicitará el consentimiento correspondiente.c) Cookies analíticas o de mediciónNos ayudan a entender cómo se utiliza Dralo, qué secciones se visitan, qué funcionalidades resultan más útiles, si existen errores técnicos y cómo podemos mejorar la plataforma.Estas cookies solo se utilizarán cuando el usuario haya dado su consentimiento.Dralo puede utilizar herramientas como Google Analytics para obtener estadísticas agregadas sobre el uso de la web. Google indica que la cookie _ga, utilizada por Google Analytics, permite distinguir visitantes y tiene una duración habitual de 2 años; además, Google Analytics permite configurar la duración de sus cookies en determinados casos. (Asistencia de Google)d) Cookies de tercerosSon cookies gestionadas por proveedores externos que prestan servicios a Dralo.Actualmente o en el futuro pueden intervenir proveedores como:Google Analytics, para análisis estadístico. PayPal o Redsys, si se habilitan pagos online. Otros proveedores técnicos necesarios para funcionalidades de plataforma, autenticación, seguridad, soporte o contenidos embebidos. Estas cookies dependerán de los servicios efectivamente integrados en cada momento.e) Cookies publicitarias o de marketingActualmente Dralo no debería instalar cookies publicitarias salvo que se incorporen herramientas específicas de marketing, remarketing, píxeles publicitarios o publicidad personalizada.Si en el futuro se utilizan cookies publicitarias, se informará previamente y se solicitará consentimiento expreso antes de instalarlas."},{"number":4,"title":"4. Cookies que podemos utilizar","body":"La siguiente tabla debe revisarse antes de publicar la política, ya que el listado exacto depende de la configuración real de la web, del gestor de consentimiento y de las herramientas activas.Cookie / tecnologíaTitularTipoFinalidadDuración aproximadaCookie de sesiónDraloTécnicaMantener la sesión del usuario y permitir el uso de la plataformaSesión o periodo limitadoCookie de consentimientoDraloTécnicaRecordar si el usuario ha aceptado, rechazado o configurado las cookies6-12 mesesCookie de seguridadDraloTécnicaAyudar a proteger formularios, accesos y sesiones frente a usos indebidosSesión o periodo limitadoCookie de preferenciasDraloPreferenciasRecordar ajustes seleccionados por el usuarioVariable_gaGoogle AnalyticsAnalíticaDistinguir visitantes y generar estadísticas de usoHasta 2 años_ga_XXXXXXXXGoogle AnalyticsAnalíticaMantener el estado de sesión y medición de eventos en GA4Hasta 2 años_gidGoogle AnalyticsAnalíticaDistinguir usuarios durante un periodo breveAproximadamente 24 horas_gat / _gat_gtag_XXXXXXXXGoogle AnalyticsAnalíticaLimitar la tasa de solicitudesAproximadamente 1 minutoCookies de PayPalPayPalTécnica / pago / seguridadGestionar pagos, prevenir fraude y mantener seguridad en el proceso de pagoSegún configuración de PayPalCookies de RedsysRedsys / entidad bancariaTécnica / pago / seguridadGestionar pagos y autenticación seguraSegún configuración de Redsys"},{"number":5,"title":"5. Base jurídica para el uso de cookies","body":"La base jurídica para utilizar cookies técnicas o necesarias es el interés legítimo de Dralo en garantizar el funcionamiento, seguridad y disponibilidad de la web, así como la prestación del servicio solicitado por el usuario.La base jurídica para utilizar cookies analíticas, publicitarias o no necesarias es el consentimiento del usuario.El usuario puede aceptar, rechazar o configurar las cookies no necesarias desde el banner o panel de configuración disponible en la web."},{"number":6,"title":"6. Cómo gestionar las cookies en","body":"DraloAl acceder a la web, el usuario puede elegir entre las siguientes opciones:Aceptar todas las cookies. Usar solo cookies necesarias o rechazar las cookies no necesarias. Configurar cookies, eligiendo qué categorías desea aceptar. El usuario puede cambiar su elección en cualquier momento desde el enlace o botón de “Ajustes de cookies” disponible en la web.Si el usuario no acepta cookies analíticas, publicitarias o de terceros no necesarias, estas no deberían instalarse."},{"number":7,"title":"7. Cómo eliminar o bloquear cookies desde el navegador","body":"Además del panel de configuración de Dralo, el usuario puede permitir, bloquear o eliminar cookies desde la configuración de su navegador.Los pasos varían según el navegador utilizado. Normalmente se encuentran en las opciones de privacidad, seguridad o configuración avanzada.El bloqueo de cookies técnicas puede afectar al funcionamiento de la web, al inicio de sesión, al registro de usuario, al acceso a recursos o al uso de determinadas funcionalidades interactivas."},{"number":8,"title":"8. Cookies de terceros y transferencias internacionales","body":"Algunas cookies de terceros pueden implicar que determinados proveedores traten información fuera del Espacio Económico Europeo.Cuando esto ocurra, Dralo procurará que dichos tratamientos se realicen con garantías adecuadas conforme a la normativa aplicable, como decisiones de adecuación, cláusulas contractuales tipo, acuerdos de tratamiento de datos u otros mecanismos válidos.Esto puede ser especialmente relevante en el caso de proveedores tecnológicos internacionales como Google, PayPal u otros servicios externos."},{"number":9,"title":"9. Cookies y usuarios menores de edad","body":"Dralo está orientado a personas que quieren preparar exámenes de inglés, y puede ser utilizado por estudiantes jóvenes.Si eres menor de 14 años, no debes aceptar cookies no necesarias ni utilizar servicios que impliquen el tratamiento de tus datos personales sin autorización de tu madre, padre, tutor o representante legal.Cuando sea razonable pensar que el usuario puede ser menor de edad, Dralo podrá adoptar medidas adicionales de información o verificación."},{"number":10,"title":"10. Cambios en la","body":"Política de CookiesDralo podrá modificar esta Política de Cookies cuando cambien las cookies utilizadas, las herramientas integradas, la configuración de la plataforma o la normativa aplicable.La versión vigente será la publicada en esta página.Texto recomendado para el banner de cookiesTe recomiendo sustituir el texto actual por este:Utilizamos cookies propias y de terceros para garantizar el funcionamiento de la web y, con tu consentimiento, analizar el uso de la plataforma y mejorar nuestros contenidos. Puedes aceptar todas las cookies, rechazar las no necesarias o configurar tus preferencias. Más información en nuestra Política de Cookies.Botones recomendados, al mismo nivel visual:Rechazar no necesariasConfigurar cookiesAceptar todasTexto recomendado para el panel de configuraciónConfiguración de cookiesPuedes elegir qué cookies permites utilizar en Dralo. Las cookies técnicas son necesarias para que la web funcione y no pueden desactivarse desde este panel.Cookies técnicas o necesariasSiempre activas.Necesarias para iniciar sesión, navegar por la web, proteger formularios, recordar tu elección de cookies y permitir el funcionamiento básico de la plataforma.Cookies de preferenciasActivar / Desactivar.Permiten recordar determinadas opciones seleccionadas por el usuario, como preferencias de uso o configuración de la plataforma.Cookies analíticasActivar / Desactivar.Nos ayudan a conocer cómo se utiliza Dralo para mejorar contenidos, detectar errores y optimizar la experiencia de aprendizaje.Cookies publicitarias o de marketingActivar / Desactivar.Actualmente Dralo no utiliza cookies publicitarias. Si en el futuro se incorporan herramientas de publicidad o remarketing, se solicitará consentimiento previo.Botones recomendados:Guardar configuraciónRechazar no necesariasAceptar todas"}]'::jsonb
)
ON CONFLICT (slug) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  categoria = EXCLUDED.categoria,
  orden = EXCLUDED.orden,
  actualizado = EXCLUDED.actualizado,
  intro = EXCLUDED.intro,
  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'terminos-condiciones',
  'Términos y condiciones de uso',
  'legal',
  3,
  '19/05/2026',
  'TÉRMINOS Y CONDICIONES DE USO – DRALOÚltima actualización: 19/05/2026Bienvenido/a a Dralo.Los presentes Términos y Condiciones regulan el acceso, navegación, registro y uso de la plataforma educativa Dralo, accesible a través de la web y servicios asociados, así como la contratación de suscripciones y funcionalidades premium.Al acceder, registrarte o utilizar Dralo, aceptas quedar vinculado/a por estas condiciones.',
  '[{"number":1,"title":"1. IDENTIFICACIÓN DEL TITULAR","body":"Titular: Carlos García CanoNombre comercial: DraloEmail de contacto: draloenglish@gmail.comWeb: DraloDralo se encuentra actualmente en proceso de consolidación y futura formalización societaria. Antes del lanzamiento comercial definitivo podrán actualizarse los datos identificativos y fiscales correspondientes."},{"number":2,"title":"2. QUÉ ES DRALO","body":"Dralo es una plataforma digital orientada al aprendizaje del inglés y preparación de exámenes.La plataforma puede incluir, entre otros:ejercicios interactivos, contenidos educativos, recursos descargables, herramientas de inteligencia artificial, comunidad de usuarios, clases o sesiones en directo, seguimiento de progreso, chat o asistencia interactiva, contenidos gratuitos y premium, y futuras funcionalidades adicionales. Dralo no constituye un organismo certificador oficial ni garantiza la obtención de títulos, certificados o resultados concretos en exámenes oficiales."},{"number":3,"title":"3. REQUISITOS DE USO","body":"Para utilizar determinadas funcionalidades será necesario crear una cuenta de usuario.La persona usuaria declara que:tiene capacidad legal suficiente para aceptar estas condiciones, facilitará información veraz y actualizada, utilizará la plataforma de forma lícita y responsable, y respetará los derechos de terceros y las normas de comunidad. Si el usuario es menor de 14 años, deberá contar con autorización de su madre, padre, tutor o representante legal."},{"number":4,"title":"4. CUENTAS DE USUARIO","body":"Cada cuenta es personal e intransferible.No está permitido:compartir credenciales, permitir el acceso simultáneo a terceros, revender cuentas, ni utilizar la plataforma de forma fraudulenta o abusiva. El usuario es responsable de:custodiar sus credenciales, mantener la confidencialidad de su contraseña, y notificar accesos no autorizados. Dralo podrá suspender o cancelar cuentas cuando existan indicios razonables de:uso fraudulento, incumplimiento contractual, actividades ilícitas, compartición de cuentas, manipulación del sistema, acoso o comportamiento inapropiado, o incumplimiento de estas condiciones."},{"number":5,"title":"5. MODALIDADES DE ACCESO","body":"Dralo puede ofrecer:a) Versión gratuitaPermite acceso limitado a determinadas funcionalidades, contenidos o recursos.La disponibilidad de la versión gratuita podrá modificarse en cualquier momento.b) Suscripciones premiumDralo puede ofrecer planes:mensuales, semestrales, anuales, u otras modalidades futuras. Las funcionalidades incluidas dependerán del plan contratado."},{"number":6,"title":"6. PRECIOS Y PAGOS","body":"Los precios aplicables serán los mostrados en el momento de la contratación.Los pagos podrán gestionarse mediante proveedores externos como:PayPal, Redsys, Stripe, u otras pasarelas equivalentes. Dralo no almacena los datos completos de tarjetas bancarias salvo indicación expresa.El usuario autoriza el cobro recurrente correspondiente a la modalidad contratada."},{"number":7,"title":"7. RENOVACIÓN AUTOMÁTICA","body":"Las suscripciones premium se renovarán automáticamente al finalizar cada periodo contratado, salvo cancelación previa por parte del usuario.La renovación se efectuará:mensual, semestral, o anualmente,según el plan seleccionado. El usuario podrá cancelar la renovación automática desde su cuenta o mediante solicitud razonable al soporte antes de la fecha de renovación.La cancelación impedirá futuras renovaciones, pero no generará devolución automática del periodo ya abonado."},{"number":8,"title":"8. DERECHO DE DESISTIMIENTO Y CONTENIDO DIGITAL","body":"De conformidad con la normativa española de consumidores y usuarios, el usuario reconoce y acepta que:el acceso a contenidos digitales, funcionalidades premium o servicios online puede comenzar inmediatamente tras la contratación, y que dicho acceso puede implicar la pérdida del derecho de desistimiento de 14 días cuando el servicio haya comenzado con consentimiento expreso del usuario. Antes de finalizar el pago, el usuario deberá aceptar expresamente:el inicio inmediato del servicio, y la posible pérdida del derecho de desistimiento conforme a la normativa aplicable."},{"number":9,"title":"9. POLÍTICA GENERAL DE REEMBOLSOS","body":"Salvo obligación legal o error técnico imputable a Dralo:no se realizarán reembolsos parciales por periodos ya iniciados, ni por falta de uso de la plataforma, ni por cancelaciones voluntarias realizadas una vez iniciado el acceso al contenido digital. No obstante, Dralo podrá valorar reembolsos excepcionales caso por caso.La política específica de reembolsos podrá desarrollarse adicionalmente en un documento independiente."},{"number":10,"title":"10. CLASES, PROFESORES Y SESIONES EN DIRECTO","body":"Dralo puede ofrecer:sesiones en directo, tutorías, prácticas, o interacción con profesores asociados o colaboradores. La disponibilidad de profesores podrá variar según:horarios, demanda, idioma, nivel, o disponibilidad operativa. Dralo no garantiza disponibilidad permanente ni asignación concreta de profesor.Las opiniones, recomendaciones o explicaciones facilitadas por profesores o colaboradores forman parte del entorno educativo y no constituyen asesoramiento profesional oficial."},{"number":11,"title":"11. GRABACIÓN DE SESIONES","body":"Dralo podrá grabar determinadas clases, sesiones o actividades en directo con finalidades como:formación, mejora del servicio, revisión de calidad, resolución de incidencias, seguridad, o acceso posterior por usuarios autorizados. La participación en determinadas sesiones puede implicar la captación de:voz, nombre de usuario, mensajes, o intervenciones realizadas durante la sesión. El tratamiento de estos datos se regula conforme a la Política de Privacidad."},{"number":12,"title":"12. HERRAMIENTAS DE INTELIGENCIA ARTIFICIAL","body":"Dralo puede utilizar herramientas de inteligencia artificial para:práctica conversacional, generación de ejercicios, corrección automática, recomendaciones, asistencia educativa, o soporte interactivo. Las respuestas generadas automáticamente:pueden contener errores, imprecisiones, resultados incompletos, o información desactualizada. La IA no sustituye el criterio humano ni garantiza resultados académicos concretos.Se recomienda no introducir:datos sensibles, contraseñas, información bancaria, ni datos personales innecesarios."},{"number":13,"title":"13. CONTENIDO GENERADO POR LOS USUARIOS","body":"Los usuarios podrán publicar o compartir:mensajes, comentarios, audios, ejercicios, textos, u otros contenidos. El usuario garantiza que:dispone de derechos suficientes sobre el contenido enviado, no infringe derechos de terceros, y que el contenido no es ilícito, ofensivo o inapropiado. Dralo podrá:moderar, revisar, ocultar, bloquear, o eliminar contenidoscuando considere que incumplen estas condiciones o puedan afectar a la plataforma o terceros."},{"number":14,"title":"14. NORMAS DE CONDUCTA","body":"Queda prohibido:acosar o insultar a otros usuarios, publicar contenido ilegal, discriminatorio o sexual, enviar spam, difundir malware, manipular la plataforma, vulnerar sistemas de seguridad, compartir cuentas, utilizar bots automatizados, copiar contenidos sin autorización, o realizar actividades que perjudiquen a Dralo o terceros."},{"number":15,"title":"15. MODERACIÓN Y CONTROL DE LA COMUNIDAD","body":"Dralo podrá realizar moderación activa y reactiva de la comunidad.Esto incluye:revisión de contenidos, atención de reportes, bloqueo temporal, suspensión, limitación de funcionalidades, o expulsión definitiva. Las decisiones de moderación podrán adoptarse para proteger:la seguridad, convivencia, integridad de menores, cumplimiento legal, y correcto funcionamiento de la plataforma."},{"number":16,"title":"16. PROPIEDAD INTELECTUAL","body":"Todos los contenidos de Dralo están protegidos por derechos de propiedad intelectual e industrial.Esto incluye:ejercicios, materiales educativos, diseños, código, interfaz, textos, logos, audios, vídeos, grabaciones, contenidos premium, prompts, y recursos descargables. No se permite:copiar, distribuir, revender, reproducir, transformar, entrenar modelos, ni explotar contenidossin autorización expresa."},{"number":17,"title":"17. DISPONIBILIDAD DEL SERVICIO","body":"Dralo no garantiza:disponibilidad ininterrumpida, ausencia de errores, compatibilidad absoluta, ni funcionamiento permanente. La plataforma puede:actualizarse, modificarse, suspender funcionalidades, entrar en mantenimiento, o evolucionar continuamente."},{"number":18,"title":"18. LIMITACIÓN DE RESPONSABILIDAD","body":"Dralo no será responsable de:decisiones tomadas exclusivamente por el usuario, errores derivados de herramientas de IA, interrupciones temporales, pérdida de datos por causas ajenas razonables, fallos de terceros, indisponibilidad temporal, ni resultados académicos concretos. La responsabilidad máxima de Dralo, cuando legalmente proceda, quedará limitada al importe efectivamente abonado por el usuario en los últimos 12 meses."},{"number":19,"title":"19. PROTECCIÓN DE DATOS Y COOKIES","body":"El tratamiento de datos personales se regula conforme a:la Política de Privacidad, y la Política de Cookies de Dralo."},{"number":20,"title":"20. MODIFICACIONES","body":"Dralo podrá modificar estos Términos y Condiciones para adaptarlos a:cambios legales, técnicos, organizativos, comerciales, o funcionales. La versión vigente será la publicada en cada momento.Cuando los cambios sean relevantes, se informará razonablemente a los usuarios."},{"number":21,"title":"21. LEGISLACIÓN APLICABLE Y JURISDICCIÓN","body":"Los presentes Términos y Condiciones se regirán por la legislación española.En caso de conflicto, las partes se someterán a los juzgados y tribunales competentes conforme a la normativa española de consumidores y usuarios.Perfecto. Con lo que me has indicado ya puedo estructurar unos Términos y Condiciones bastante sólidos para Dralo.Tu caso ya no es una simple “web educativa”, sino una plataforma con:servicio digital educativo, comunidad de usuarios, suscripciones, contenidos premium, interacción entre usuarios, IA integrada, profesores externos asociados, subida de contenido, y posible acceso de menores. Eso implica que los Términos deben cubrir bastante más que un aviso legal estándar.Lo que incluiré en los Términos y Condiciones"},{"number":1,"title":"1. Objeto del servicio","body":"Definir claramente:qué es Dralo, qué ofrece, qué NO garantiza, y que se trata de apoyo educativo, no certificación oficial."},{"number":2,"title":"2. Sección 2","body":"Registro y cuentascuentas gratuitas y premium, veracidad de datos, seguridad de credenciales, suspensión/cancelación de cuentas."},{"number":3,"title":"3. Suscripciones y pagos","body":"Adaptado a:mensual, semestral, anual. Incluiré:renovación, cancelación, cambios de precio, impagos, interrupción del servicio."},{"number":4,"title":"4. Política de reembolsos","body":"Muy importante para contenido digital en España.Aquí hay una cuestión legal clave:Cuando el usuario accede inmediatamente al contenido digital/suscripción, normalmente:pierde el derecho de desistimiento de 14 días, PERO solo si lo aceptáis correctamente antes del pago. Esto hay que redactarlo MUY bien para cumplir:Ley General para la Defensa de los Consumidores y Usuarios y normativa UE de contenidos digitales. Os recomendaré incluir:checkbox específica antes de pagar, aceptación expresa de inicio inmediato del servicio, reconocimiento de pérdida del desistimiento. Si esto no se hace bien, un usuario podría reclamar devoluciones incluso después de consumir contenido."},{"number":5,"title":"5. Profesores asociados","body":"Hay que aclarar:si son empleados, colaboradores, o simplemente usuarios verificados. También limitar responsabilidad sobre:disponibilidad, opiniones, recomendaciones, sesiones en directo."},{"number":6,"title":"6. Comunidad y contenido generado por usuarios","body":"Esto es MUY importante porque permitís:audios, textos, comentarios, interacción entre usuarios. Necesitáis normas sobre:conducta, prohibiciones, copyright, acoso, spam, contenido ilegal, moderación, eliminación de contenido."},{"number":7,"title":"7. Menores","body":"Como probablemente habrá menores:incluiré cláusulas reforzadas, consentimiento parental para menores de 14, limitaciones de uso, y recomendaciones de supervisión."},{"number":8,"title":"8. Inteligencia artificial","body":"Muy importante también.Debe aclararse que:la IA puede cometer errores, no sustituye profesores, no garantiza exactitud absoluta, no debe usarse para decisiones relevantes, y no deben introducirse datos sensibles."},{"number":9,"title":"9. Disponibilidad del servicio","body":"Para protegeros frente a:caídas, bugs, mantenimiento, errores, cambios de funcionalidades, beta features."},{"number":10,"title":"10. Propiedad intelectual","body":"Protección de:ejercicios, materiales, prompts, clases, contenidos premium, comunidad, branding, IA, recursos descargables."},{"number":11,"title":"11. Limitación de responsabilidad","body":"Especialmente importante por:aprendizaje, exámenes oficiales, IA, profesores, comunidad, contenido subido por usuarios."},{"number":12,"title":"12. Resolución de conflictos","body":"Lo adaptaré solo a España como me has indicado.Lo que todavía os recomendaría decidirAntes de publicar definitivamente:si las suscripciones se renuevan automáticamente, si habrá periodo de prueba, si permitiréis compartir cuenta, si habrá certificados propios, si guardaréis grabaciones de clases, y si la comunidad tendrá moderación activa o reactiva. Eso cambia bastante el riesgo legal.Mi recomendación jurídica para DraloPor vuestro modelo, os recomendaría tener separados:Aviso Legal Política de Privacidad Política de Cookies Términos y Condiciones Política de Reembolsos (o integrada dentro de términos) Normas de Comunidad Porque la parte social/comunidad os expone bastante más que una academia tradicional.Y especialmente importante:si usáis IA + menores + comunidad,la moderación y reporting de contenido deberían existir desde el inicio.Además, ahora ya quedan claras varias cuestiones legales importantes:la suscripción es recurrente y con renovación automática, existe una modalidad freemium, las cuentas son personales e intransferibles, habrá almacenamiento de grabaciones, existe moderación de comunidad, y no se ofrecen certificados oficiales. Eso reduce bastante ambigüedades jurídicas.Hay 4 puntos importantes que os recomiendo implementar técnicamente sí o sí"},{"number":1,"title":"1. Checkbox especial antes del pago","body":"Esto es MUY importante legalmente.Antes de contratar una suscripción premium deberíais incluir algo parecido a:“Solicito el acceso inmediato al contenido digital y entiendo que, una vez iniciado el servicio, puedo perder mi derecho de desistimiento conforme a la normativa de consumidores.”Sin esto, podéis tener problemas con reclamaciones de reembolso."},{"number":2,"title":"2. Renovación automática claramente visible","body":"La renovación automática:debe explicarse antes del pago, no escondida en términos legales. Por ejemplo:“Suscripción renovable automáticamente cada mes hasta cancelación.” Y el usuario debe poder cancelar fácilmente desde su cuenta."},{"number":3,"title":"3. Moderación de comunidad","body":"Como habrá:mensajes, comentarios, audios, interacción entre usuarios, posiblemente menores, necesitáis:botón/reportar contenido, posibilidad de expulsión, reglas de conducta, moderación de acoso/spam, y capacidad de borrar contenido. Esto es especialmente importante en España y UE."},{"number":4,"title":"4. Grabaciones de clases","body":"Si vais a guardar grabaciones:debéis avisarlo claramente, explicar finalidad, duración aproximada, quién puede acceder, y si aparecen voces/imágenes de alumnos. Porque eso entra directamente en protección de datos.Jurídicamente, Dralo ahora encaja más en:plataforma educativa digital, SaaS educativo, comunidad online, proveedor de contenidos digitales, con componentes de IA y comunicación entre usuarios. Y eso significa que vuestros Términos deben ser bastante más completos que los de una academia tradicional.Lo siguiente que haría yoYa os prepararía:Términos y Condiciones completos. Política de Reembolsos integrada. Normas de Comunidad. Cláusulas específicas para: IA, menores, grabaciones, renovación automática, profesores asociados. Porque ahora mismo ya tengo suficiente contexto para redactarlo correctamente."}]'::jsonb
)
ON CONFLICT (slug) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  categoria = EXCLUDED.categoria,
  orden = EXCLUDED.orden,
  actualizado = EXCLUDED.actualizado,
  intro = EXCLUDED.intro,
  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'proteccion-datos',
  'Protección de datos',
  'privacidad',
  4,
  '19/05/2026',
  'En Dralo tratamos tus datos personales conforme al RGPD y la normativa española aplicable.',
  '[{"number":11,"title":"11. Menores de edad","body":"Dralo está dirigido a personas interesadas en preparar exámenes oficiales de inglés. Aunque el servicio puede resultar útil para estudiantes menores de edad, no está específicamente diseñado para recoger datos de menores de 14 años sin autorización de sus representantes legales.Si eres menor de 14 años, no debes registrarte ni enviar datos personales sin el consentimiento de tu madre, padre, tutor o representante legal.Si Dralo detecta que ha recogido datos de un menor de 14 años sin la autorización correspondiente, adoptará medidas razonables para eliminar dichos datos o solicitar la autorización necesaria.En caso de que seas madre, padre, tutor o representante legal y creas que un menor ha facilitado datos personales en Dralo sin autorización, puedes contactar con nosotros en draloenglish@gmail.com"},{"number":12,"title":"12. Derechos de las personas usuarias","body":"Puedes ejercer los siguientes derechos en materia de protección de datos:Derecho de acceso: saber qué datos tratamos sobre ti. Derecho de rectificación: corregir datos inexactos o incompletos. Derecho de supresión: solicitar la eliminación de tus datos. Derecho de oposición: oponerte a determinados tratamientos. Derecho de limitación: solicitar que limitemos el tratamiento de tus datos. Derecho de portabilidad: recibir tus datos en formato estructurado, cuando proceda. Derecho a retirar el consentimiento en cualquier momento, sin que ello afecte a la licitud del tratamiento realizado previamente. Para ejercer tus derechos, puedes escribir a:Email: draloenglish@gmail.comAsunto recomendado: “Ejercicio de derechos de protección de datos”Podremos solicitar información adicional para verificar tu identidad cuando sea necesario.Si consideras que no hemos tratado tus datos correctamente, también puedes presentar una reclamación ante la Agencia Española de Protección de Datos (AEPD)."},{"number":13,"title":"13. Seguridad de los datos","body":"Dralo aplica medidas técnicas y organizativas razonables para proteger los datos personales frente a pérdida, uso indebido, acceso no autorizado, alteración, divulgación o destrucción.Entre otras medidas, la plataforma puede utilizar cifrado de comunicaciones mediante HTTPS, control de accesos, autenticación de usuarios, limitación de permisos, revisión de incidencias, registros técnicos y medidas de seguridad asociadas al hosting y a los proveedores tecnológicos utilizados.No obstante, ningún sistema conectado a Internet puede garantizar una seguridad absoluta, por lo que el usuario también debe adoptar medidas razonables, como proteger sus credenciales de acceso y no compartir contraseñas."},{"number":14,"title":"14. Exactitud de los datos","body":"El usuario garantiza que los datos personales facilitados son veraces, exactos y actualizados.Si tus datos cambian, deberás comunicárnoslo o actualizarlos desde tu cuenta."},{"number":15,"title":"15. Datos de terceros","body":"No debes facilitar datos personales de otras personas salvo que cuentes con autorización suficiente para hacerlo.En particular, no debes introducir en formularios, ejercicios, chats o mensajes datos personales de terceros, información sensible o contenidos que no sean necesarios para el uso educativo de la plataforma."},{"number":16,"title":"16. Baja de cuenta","body":"Puedes solicitar la eliminación de tu cuenta escribiendo a draloenglish@gmail.com o utilizando las opciones disponibles en la plataforma.La eliminación de la cuenta puede implicar la pérdida de acceso a contenidos, progreso, historial de ejercicios, configuraciones y funcionalidades asociadas.Determinados datos podrán conservarse bloqueados cuando sea necesario para cumplir obligaciones legales, atender responsabilidades o garantizar la seguridad de la plataforma."},{"number":17,"title":"17. Cambios en esta","body":"Política de PrivacidadDralo podrá modificar esta Política de Privacidad para adaptarla a cambios legales, técnicos, organizativos o funcionales.Cuando los cambios sean relevantes, se informará a los usuarios por medios razonables, como aviso en la web, comunicación por email o notificación dentro de la plataforma.La versión vigente será la publicada en cada momento en esta página."}]'::jsonb
)
ON CONFLICT (slug) DO UPDATE SET
  titulo = EXCLUDED.titulo,
