  orden = EXCLUDED.orden,
  actualizado = EXCLUDED.actualizado,
  intro = EXCLUDED.intro,
  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'aviso-legal',
  'Aviso legal',
  'legal',
  5,
  '19/05/2026',
  'AVISO LEGALÚltima actualización: 19/05/2026Bienvenido/a a Dralo.El presente Aviso Legal regula el acceso, navegación y uso del sitio web y plataforma accesible desde Dralo, así como de los contenidos, funcionalidades y servicios ofrecidos a través del mismo.',
  '[{"number":1,"title":"1. Identificación del titular","body":"Dralo es un proyecto digital en fase inicial de desarrollo orientado al aprendizaje del inglés y preparación de exámenes oficiales.Actualmente, Dralo se encuentra en fase pre-lanzamiento y en proceso de definición y formalización de su estructura jurídica y operativa.Mientras se completa dicho proceso, para cualquier consulta legal, incidencia o comunicación relacionada con la plataforma, puedes contactar a través de:Email de contacto: draloenglish@gmail.com Web: Dralo Antes del lanzamiento comercial definitivo o de la activación de servicios de pago, este Aviso Legal será actualizado con los datos completos del titular o entidad responsable conforme a la normativa aplicable."},{"number":2,"title":"2. Objeto","body":"El presente sitio web tiene como finalidad ofrecer información, recursos y funcionalidades relacionadas con el aprendizaje del inglés, entrenamiento educativo, preparación de exámenes oficiales y herramientas interactivas asociadas.Dralo puede incluir:contenidos formativos, ejercicios y pruebas, funcionalidades interactivas, herramientas basadas en inteligencia artificial, áreas de usuario, recursos descargables, y futuras funcionalidades premium o de pago. El acceso a determinadas funcionalidades puede requerir registro previo."},{"number":3,"title":"3. Condiciones de acceso y uso","body":"El acceso a la web tiene carácter gratuito, sin perjuicio de que determinadas funcionalidades o servicios puedan requerir registro o contratación.La persona usuaria se compromete a utilizar Dralo de forma lícita, responsable y conforme a:la legislación aplicable, la buena fe, el presente Aviso Legal, y los derechos de terceros. Queda prohibido:utilizar la plataforma para actividades ilícitas o fraudulentas, intentar acceder sin autorización a sistemas o cuentas, introducir malware, bots o herramientas automatizadas abusivas, vulnerar medidas de seguridad, utilizar la plataforma para enviar spam, copiar, extraer o reutilizar contenidos sin autorización, o utilizar los servicios de forma que pueda perjudicar a Dralo o a otras personas usuarias. Dralo podrá limitar, suspender o bloquear el acceso a usuarios que incumplan estas condiciones."},{"number":4,"title":"4. Registro de usuarios","body":"Algunas funcionalidades pueden requerir la creación de una cuenta.La persona usuaria será responsable de:mantener la confidencialidad de sus credenciales, custodiar adecuadamente sus contraseñas, y notificar cualquier acceso no autorizado o incidencia de seguridad. Dralo podrá cancelar cuentas fraudulentas, inactivas o que incumplan las condiciones de uso."},{"number":5,"title":"5. Herramientas de inteligencia artificial","body":"Dralo puede incorporar funcionalidades basadas en inteligencia artificial para:práctica conversacional, generación de ejercicios, corrección automática, asistencia educativa, recomendaciones, o explicaciones formativas. Las respuestas generadas automáticamente pueden contener errores, imprecisiones o resultados no actualizados, por lo que no deben interpretarse como asesoramiento profesional, académico oficial ni garantía absoluta de exactitud.La persona usuaria es responsable del uso que haga de las funcionalidades de IA y se recomienda no introducir:datos sensibles, información confidencial, contraseñas, datos bancarios, ni datos personales de terceros. Dralo podrá utilizar proveedores tecnológicos externos especializados en inteligencia artificial para prestar estas funcionalidades."},{"number":6,"title":"6. Propiedad intelectual e industrial","body":"Todos los contenidos de Dralo, incluyendo:textos, diseños, logotipos, marcas, ejercicios, recursos, código, bases de datos, interfaces, imágenes, materiales educativos, y demás elementos de la plataforma, están protegidos por derechos de propiedad intelectual e industrial y corresponden a Dralo o a sus respectivos titulares.No se permite:reproducir, distribuir, transformar, comunicar públicamente, extraer, reutilizar, ni explotar los contenidos sin autorización previa y expresa. El acceso a la plataforma no implica cesión de derechos sobre los contenidos."},{"number":7,"title":"7. Enlaces externos","body":"La web puede incluir enlaces a páginas o servicios de terceros.Dralo no controla ni asume responsabilidad sobre:contenidos externos, políticas de privacidad, disponibilidad, seguridad, o funcionamiento de sitios ajenos. La inclusión de enlaces no implica relación, recomendación ni aprobación por parte de Dralo."},{"number":8,"title":"8. Disponibilidad y responsabilidad","body":"Dralo realiza esfuerzos razonables para mantener la plataforma disponible y segura, aunque no garantiza:disponibilidad permanente, ausencia de errores, continuidad del servicio, ni inexistencia de interrupciones técnicas. La plataforma puede encontrarse en fase beta, pruebas o desarrollo continuo.Dralo no será responsable de:daños derivados del uso de la web, interrupciones temporales, pérdida de información, incompatibilidades técnicas, errores en contenidos, ni decisiones tomadas exclusivamente a partir de información generada automáticamente."},{"number":9,"title":"9. Protección de datos y cookies","body":"El tratamiento de datos personales se regula conforme a la Política de Privacidad y la Política de Cookies de Dralo.Puedes consultar dichos documentos en:Política de Privacidad Política de Cookies"},{"number":10,"title":"10. Modificaciones","body":"Dralo podrá modificar este Aviso Legal para adaptarlo a cambios legales, técnicos, organizativos o funcionales.La versión vigente será la publicada en cada momento en esta página."},{"number":11,"title":"11. Legislación aplicable y jurisdicción","body":"El presente Aviso Legal se regirá por la legislación española y normativa europea aplicable.En caso de conflicto o controversia, las partes se someterán a los juzgados y tribunales que correspondan conforme a la normativa de consumidores y usuarios aplicable."}]'::jsonb
)
