  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'normas-comunidad',
  'Normas de comunidad',
  'comunidad',
  6,
  '19/05/2026',
  'NORMAS DE COMUNIDAD – DRALOÚltima actualización: 19/05/2026La comunidad de Dralo está diseñada para crear un entorno seguro, educativo, respetuoso y útil para todas las personas usuarias.Estas Normas de Comunidad regulan la participación en:chats, comentarios, foros, clases en directo, grupos, ejercicios colaborativos, intercambio de audios o mensajes, y cualquier espacio interactivo de Dralo. Al utilizar la comunidad, aceptas cumplir estas normas.',
  '[{"number":1,"title":"1. OBJETIVO DE LA COMUNIDAD","body":"La comunidad de Dralo tiene como finalidad:practicar inglés, resolver dudas, compartir recursos, colaborar con otros estudiantes, participar en actividades educativas, y fomentar un entorno positivo de aprendizaje. Esperamos que todas las personas usuarias actúen con:respeto, educación, responsabilidad, y buena fe."},{"number":2,"title":"2. RESPETO Y CONVIVENCIA","body":"No está permitido:insultar, acosar, intimidar, amenazar, humillar, discriminar, provocar conflictos deliberadamente, ni mantener comportamientos tóxicos hacia otros usuarios, profesores o moderadores. Esto incluye conductas relacionadas con:raza, nacionalidad, religión, orientación sexual, identidad de género, discapacidad, apariencia física, edad, o cualquier otra circunstancia personal. Dralo podrá actuar incluso aunque el comportamiento ocurra de forma reiterada, indirecta o aparentemente “en broma”."},{"number":3,"title":"3. CONTENIDO PROHIBIDO","body":"No se permite publicar, compartir, enviar o almacenar contenido:ilegal, violento, pornográfico, sexual explícito, ofensivo, discriminatorio, difamatorio, amenazante, fraudulento, o que vulnere derechos de terceros. Tampoco está permitido:compartir malware, enlaces peligrosos, spam, publicidad no autorizada, cadenas, bots, scripts automatizados, ni intentos de phishing o fraude."},{"number":4,"title":"4. PROTECCIÓN DE MENORES","body":"Dralo puede ser utilizado por estudiantes menores de edad.Por ello:queda estrictamente prohibido cualquier comportamiento inapropiado hacia menores, solicitudes de información personal sensible, acoso, sexualización, grooming, manipulación, o intentos de contacto indebido fuera de la plataforma. Cualquier conducta sospechosa podrá implicar:expulsión inmediata, bloqueo permanente, y comunicación a las autoridades competentes cuando proceda."},{"number":5,"title":"5. USO ADECUADO DE LOS CHATS Y COMUNIDAD","body":"Los espacios comunitarios deben utilizarse principalmente para:aprendizaje, práctica de idiomas, colaboración educativa, y participación respetuosa. No está permitido:sabotear conversaciones, saturar chats, enviar mensajes repetitivos, generar conflictos deliberadamente, difundir desinformación, ni dificultar el funcionamiento normal de la comunidad."},{"number":6,"title":"6. AUDIOS, IMÁGENES Y CONTENIDO SUBIDO POR USUARIOS","body":"Cuando compartas:audios, imágenes, textos, ejercicios, comentarios, grabaciones, o cualquier contenido, garantizas que:tienes derecho a compartirlo, no vulnera derechos de terceros, y cumple estas normas. No debes subir:datos personales sensibles, documentos oficiales, información bancaria, datos de terceros sin autorización, ni contenido privado o confidencial."},{"number":7,"title":"7. PROPIEDAD INTELECTUAL","body":"No está permitido:copiar materiales premium, redistribuir ejercicios, grabar clases sin autorización, compartir contenidos de pago fuera de la plataforma, ni utilizar recursos de Dralo con fines comerciales sin permiso. También se prohíbe subir contenido que infrinja:derechos de autor, marcas, licencias, o propiedad intelectual de terceros."},{"number":8,"title":"8. CUENTAS PERSONALES","body":"Las cuentas de Dralo son:personales, individuales, e intransferibles. No está permitido:compartir cuentas, vender accesos, prestar perfiles, ni utilizar cuentas de otras personas. La detección de uso compartido podrá implicar:limitación de acceso, suspensión, cancelación de la suscripción, o cierre permanente de la cuenta."},{"number":9,"title":"9. IA, AUTOMATIZACIÓN Y USO ABUSIVO","body":"No está permitido:utilizar bots para automatizar actividades, extraer masivamente contenidos, manipular ejercicios o estadísticas, intentar vulnerar sistemas de seguridad, ni utilizar herramientas automatizadas de forma abusiva. Tampoco está permitido usar la plataforma para:entrenar modelos externos, scraping, minería de datos, o reproducción masiva de contenidos."},{"number":10,"title":"10. MODERACIÓN DE LA COMUNIDAD","body":"Dralo podrá realizar moderación:activa, preventiva, manual, automatizada, o reactiva. Los moderadores podrán:revisar contenidos, eliminar publicaciones, limitar funcionalidades, silenciar usuarios, suspender cuentas, o expulsar usuarios definitivamente. Las decisiones de moderación se adoptarán para proteger:la seguridad, convivencia, legalidad, integridad de menores, y correcto funcionamiento de la plataforma."},{"number":11,"title":"11. REPORTES Y DENUNCIAS","body":"Las personas usuarias podrán reportar:comportamientos inapropiados, contenido ofensivo, spam, acoso, fraude, o posibles incumplimientos. Dralo intentará revisar los reportes en un plazo razonable.El abuso del sistema de denuncias también podrá ser sancionado."},{"number":12,"title":"12. SANCIONES Y MEDIDAS","body":"El incumplimiento de estas normas podrá implicar:advertencias, eliminación de contenido, limitación temporal, suspensión, expulsión permanente, cancelación de suscripciones, o bloqueo de acceso. En casos graves, Dralo podrá:conservar evidencias, colaborar con autoridades, o ejercer acciones legales."},{"number":13,"title":"13. PRIVACIDAD Y SEGURIDAD","body":"Respeta la privacidad de otras personas.No debes:publicar datos personales ajenos, compartir conversaciones privadas sin permiso, difundir grabaciones de clases, ni revelar información confidencial de otros usuarios."},{"number":14,"title":"14. CAMBIOS EN LAS NORMAS","body":"Dralo podrá actualizar estas Normas de Comunidad para adaptarlas a:cambios legales, nuevas funcionalidades, evolución de la plataforma, o necesidades de moderación. La versión vigente será la publicada en cada momento."},{"number":15,"title":"15. CONTACTO","body":"Si necesitas reportar incidencias o contactar con el equipo de moderación, puedes escribir a:Email: draloenglish@gmail.com"},{"number":16,"title":"16. LEGISLACIÓN APLICABLE","body":"Estas Normas de Comunidad se rigen por la legislación española y normativa aplicable en materia digital, protección de datos y servicios online."}]'::jsonb
)
