  orden = EXCLUDED.orden,
  actualizado = EXCLUDED.actualizado,
  intro = EXCLUDED.intro,
  secciones = EXCLUDED.secciones,
  updated_at = now();

INSERT INTO public.politicas (slug, titulo, categoria, orden, actualizado, intro, secciones)
VALUES (
  'politica-reembolsos',
  'Política de reembolsos',
  'comercial',
  7,
  '19/05/2026',
  'POLÍTICA DE REEMBOLSOS – DRALOÚltima actualización: 19/05/2026En Dralo queremos ofrecer una experiencia transparente y clara respecto a las suscripciones, pagos y posibles reembolsos relacionados con el uso de nuestra plataforma educativa.La presente Política de Reembolsos regula las condiciones aplicables a:suscripciones premium, pagos recurrentes, acceso a contenidos digitales, clases y funcionalidades asociadas, y cualquier servicio de pago ofrecido por Dralo. Al contratar cualquier servicio de pago de Dralo, aceptas esta política.',
  '[{"number":1,"title":"1. NATURALEZA DEL SERVICIO","body":"Dralo ofrece contenidos y servicios digitales relacionados con:aprendizaje del inglés, preparación de exámenes, acceso a plataforma educativa, herramientas interactivas, funcionalidades basadas en inteligencia artificial, comunidad, y sesiones o clases online. Los servicios contratados tienen naturaleza de contenido digital y acceso online inmediato."},{"number":2,"title":"2. SUSCRIPCIONES Y RENOVACIÓN AUTOMÁTICA","body":"Las suscripciones de Dralo pueden contratarse en modalidad:mensual, semestral, anual, u otras modalidades futuras. Todas las suscripciones premium se renuevan automáticamente al finalizar el periodo contratado, salvo cancelación previa por parte del usuario.La renovación se realizará utilizando el método de pago facilitado durante la contratación.El usuario puede cancelar la renovación automática en cualquier momento antes de la siguiente fecha de cobro.La cancelación:evita futuros cargos, pero no implica devolución automática del periodo ya abonado."},{"number":3,"title":"3. DERECHO DE DESISTIMIENTO Y CONTENIDO DIGITAL","body":"De conformidad con la normativa española y europea de consumidores y usuarios, el usuario reconoce expresamente que:el acceso a los contenidos y funcionalidades premium puede comenzar inmediatamente tras el pago, y que dicho acceso supone el suministro de contenido digital no prestado en soporte físico. Por ello, al contratar una suscripción premium, el usuario acepta expresamente:el inicio inmediato del servicio, y entiende que puede perder su derecho de desistimiento de 14 días una vez iniciado el acceso al contenido digital. Esta aceptación deberá realizarse expresamente antes de completar el pago."},{"number":4,"title":"4. CASOS EN LOS QUE NO PROCEDE REEMBOLSO","body":"Salvo obligación legal aplicable o decisión expresa de Dralo, no procederán reembolsos en los siguientes casos:falta de uso de la plataforma, olvido de cancelación de la renovación automática, insatisfacción subjetiva con el contenido, incompatibilidades derivadas del dispositivo o conexión del usuario no atribuibles a Dralo, suspensión por incumplimiento de normas, bloqueo de cuenta por uso indebido, expulsión de la comunidad por incumplimiento de las condiciones, pérdida de acceso por compartir cuentas, cancelaciones realizadas una vez iniciado el periodo de suscripción, o acceso efectivo a contenidos digitales premium."},{"number":5,"title":"5. REEMBOLSOS EXCEPCIONALES","body":"Dralo podrá valorar reembolsos parciales o totales de forma excepcional cuando existan circunstancias justificadas, como por ejemplo:cobros duplicados, errores técnicos atribuibles a la plataforma, fallos graves y continuados del servicio, acceso imposible por causas imputables exclusivamente a Dralo, o incidencias verificadas de facturación. Cada solicitud será revisada individualmente.La aprobación de un reembolso excepcional en un caso concreto no crea obligación de conceder reembolsos similares en el futuro."},{"number":6,"title":"6. PRUEBA GRATUITA Y VERSIÓN FREE","body":"Dralo puede ofrecer:funcionalidades gratuitas, acceso parcial sin coste, o versiones de prueba. La existencia de una modalidad gratuita permite al usuario conocer parcialmente la plataforma antes de contratar una suscripción premium."},{"number":7,"title":"7. CANCELACIÓN DE SUSCRIPCIONES","body":"El usuario puede cancelar su suscripción premium en cualquier momento desde:su cuenta de usuario, el panel de configuración, o mediante contacto razonable con soporte. La cancelación:no elimina automáticamente la cuenta, y no implica devolución del periodo ya abonado. Tras la cancelación, el acceso premium permanecerá activo hasta finalizar el periodo contratado."},{"number":8,"title":"8. PAGOS FRAUDULENTOS O USO ABUSIVO","body":"Dralo podrá:bloquear cuentas, suspender servicios, cancelar accesos, o rechazar solicitudes de reembolsocuando existan indicios razonables de: fraude, abuso, uso indebido, manipulación del sistema, compartición de cuentas, devolución fraudulenta de cargos (“chargebacks”), o incumplimiento de las condiciones de uso."},{"number":9,"title":"9. CLASES, SESIONES Y CONTENIDO EN DIRECTO","body":"Cuando Dralo ofrezca:clases en directo, tutorías, prácticas, sesiones grupales, o actividades similares, la no asistencia del usuario no dará derecho automático a reembolso.En determinados casos, Dralo podrá:reprogramar sesiones, ofrecer acceso a grabaciones, o facilitar alternativas razonables."},{"number":10,"title":"10. GRABACIONES Y CONTENIDO DISPONIBLE","body":"El acceso a grabaciones, materiales o contenidos publicados tras la contratación se considera parte del servicio digital prestado.El hecho de que el usuario no visualice dichos contenidos no implica derecho a devolución."},{"number":11,"title":"11. PLAZO Y FORMA DE SOLICITAR UN REEMBOLSO","body":"Las solicitudes de reembolso deberán realizarse mediante:email a draloenglish@gmail.com, o mediante los canales habilitados en la plataforma. La solicitud deberá incluir:email asociado a la cuenta, fecha aproximada del cobro, motivo de la solicitud, y cualquier información relevante. Dralo podrá solicitar información adicional para verificar la incidencia."},{"number":12,"title":"12. PLAZO DE RESOLUCIÓN","body":"Dralo intentará responder las solicitudes de reembolso en un plazo razonable.En caso de aprobarse un reembolso:este podrá realizarse mediante el mismo método de pago utilizado originalmente, y el plazo efectivo dependerá de la entidad bancaria o proveedor de pago."},{"number":13,"title":"13. MODIFICACIONES DE ESTA POLÍTICA","body":"Dralo podrá modificar esta Política de Reembolsos para adaptarla a:cambios legales, técnicos, comerciales, o funcionales. La versión vigente será la publicada en la web en cada momento."},{"number":14,"title":"14. LEGISLACIÓN APLICABLE","body":"La presente Política de Reembolsos se regirá por la legislación española y normativa europea aplicable en materia de consumidores y servicios digitales."}]'::jsonb
)
